    ui_scale_auto = {
        us = 'UI Scale follows the scale Windows uses on the display the game is on (Settings, Display, Scale): 150 % there gives 150 % here. Moving the window to another display changes it.',
        ru = 'Масштаб интерфейса следует масштабу Windows для экрана, на котором игра (Параметры, Дисплей, Масштаб): 150 % там — 150 % здесь. Перенос окна на другой экран меняет его.',
        de = 'Die UI-Skalierung folgt der Skalierung, die Windows für den Bildschirm des Spiels nutzt (Einstellungen, Anzeige, Skalierung): 150 % dort ergeben 150 % hier. Verschiebt man das Fenster auf einen anderen Bildschirm, ändert sie sich.',
        fr = "L'échelle de l'interface suit celle que Windows utilise pour l'écran du jeu (Paramètres, Affichage, Échelle) : 150 % là-bas donne 150 % ici. Déplacer la fenêtre sur un autre écran la change.",
        pl = 'Skala interfejsu podąża za skalą Windows na ekranie z grą (Ustawienia, Ekran, Skala): 150% tam daje 150% tutaj. Przeniesienie okna na inny ekran ją zmienia.',
        es = 'La escala de la interfaz sigue la que Windows usa en la pantalla del juego (Configuración, Pantalla, Escala): 150 % allí da 150 % aquí. Mover la ventana a otra pantalla la cambia.',
        it = "La scala dell'interfaccia segue quella che Windows usa sullo schermo del gioco (Impostazioni, Schermo, Ridimensionamento): 150% lì dà 150% qui. Spostare la finestra su un altro schermo la cambia.",
        cz = 'Měřítko rozhraní sleduje měřítko Windows na obrazovce se hrou (Nastavení, Displej, Měřítko): 150 % tam dává 150 % tady. Přesun okna na jinou obrazovku ho změní.',
        cn = '界面缩放跟随 Windows 在游戏所在显示器上的缩放（设置、显示、缩放）：那里 150% 这里就是 150%。把窗口移到另一台显示器会随之改变。',
        tw = '介面縮放跟隨 Windows 在遊戲所在顯示器上的縮放（設定、顯示器、縮放）：那裡 150% 這裡就是 150%。把視窗移到另一台顯示器會隨之改變。',
        ko = 'UI 배율이 게임이 있는 디스플레이의 Windows 배율(설정, 디스플레이, 배율)을 따릅니다. 그곳이 150%면 여기도 150%입니다. 창을 다른 디스플레이로 옮기면 바뀝니다.',
        kk = 'Интерфейс масштабы ойын тұрған экрандағы Windows масштабына ереді (Параметрлер, Дисплей, Масштаб): онда 150 % болса, мұнда да 150 %. Терезені басқа экранға жылжытсаңыз, ол өзгереді.',
    },
    fafre_menu_battle = {
        us = 'AI armies fight on a small map behind the launcher, the camera following their fights. Off shows the menu movie instead and uses less of the computer.',
        ru = 'За лаунчером на небольшой карте сражаются армии ИИ, камера следит за боями. Выключено: вместо этого видео меню, нагрузка на компьютер меньше.',
        de = 'KI-Armeen kämpfen auf einer kleinen Karte hinter dem Launcher, die Kamera folgt ihren Gefechten. Aus zeigt stattdessen das Menüvideo und braucht weniger Rechenleistung.',
        fr = "Des armées d'IA s'affrontent sur une petite carte derrière le lanceur, la caméra suit leurs combats. Désactivé : la vidéo du menu à la place, et moins de charge pour l'ordinateur.",
        pl = 'Armie SI walczą na małej mapie za launcherem, a kamera śledzi ich starcia. Wyłączone: zamiast tego film menu i mniejsze obciążenie komputera.',
        es = 'Ejércitos de la IA combaten en un mapa pequeño detrás del lanzador y la cámara sigue sus batallas. Desactivado: el vídeo del menú en su lugar, con menos carga para el ordenador.',
        it = "Eserciti dell'IA combattono su una piccola mappa dietro il launcher e la telecamera segue gli scontri. Disattivato: al suo posto il video del menu, con meno carico per il computer.",
        cz = 'Za spouštěčem bojují armády AI na malé mapě a kamera sleduje jejich střety. Vypnuto: místo toho video menu a menší zátěž počítače.',
        cn = 'AI 军队在启动器背后的小地图上交战，镜头跟随战斗。关闭后改为播放菜单视频，占用更少的电脑资源。',
        tw = 'AI 軍隊在啟動器背後的小地圖上交戰，鏡頭跟隨戰鬥。關閉後改為播放選單影片，佔用較少的電腦資源。',
        ko = '런처 뒤의 작은 맵에서 AI 군대가 싸우고 카메라가 전투를 따라갑니다. 끄면 대신 메뉴 영상이 나오고 컴퓨터 부담이 줄어듭니다.',
        kk = 'Лаунчердің артындағы шағын картада ЖИ әскерлері соғысады, камера шайқастарды бақылайды. Өшірулі болса, оның орнына мәзір бейнесі көрсетіледі және компьютерге жүктеме азаяды.',
    },
    fafre_reduce_motion = {
        us = 'Turns off the launcher\'s motion: pages, dialogs and lists show at once instead of sliding and fading in, and buttons change colour without easing.',
        ru = 'Отключает анимации лаунчера: страницы, окна и списки появляются сразу, без сдвига и плавного появления, а кнопки меняют цвет без перехода.',
        de = 'Schaltet die Bewegungen des Launchers ab: Seiten, Dialoge und Listen erscheinen sofort statt einzugleiten und einzublenden, Schaltflächen wechseln die Farbe ohne Übergang.',
        fr = "Désactive les animations du lanceur : pages, fenêtres et listes s'affichent d'un coup au lieu de glisser et d'apparaître en fondu, et les boutons changent de couleur sans transition.",
        pl = 'Wyłącza animacje launchera: strony, okna i listy pojawiają się od razu zamiast wsuwać się i rozjaśniać, a przyciski zmieniają kolor bez przejścia.',
        es = 'Desactiva las animaciones del lanzador: páginas, diálogos y listas aparecen de golpe en lugar de deslizarse y fundirse, y los botones cambian de color sin transición.',
        it = 'Disattiva le animazioni del launcher: pagine, finestre ed elenchi compaiono subito invece di scorrere e sfumare, e i pulsanti cambiano colore senza transizione.',
        cz = 'Vypne animace spouštěče: stránky, dialogy a seznamy se ukážou hned místo zasunutí a prolnutí a tlačítka mění barvu bez přechodu.',
        cn = '关闭启动器的动画：页面、对话框和列表直接显示，不再滑入和淡入；按钮变色也不再过渡。',
        tw = '關閉啟動器的動畫：頁面、對話框和清單直接顯示，不再滑入和淡入；按鈕變色也不再過渡。',
        ko = '런처의 움직임을 끕니다. 페이지, 대화 상자, 목록이 미끄러지거나 서서히 나타나지 않고 바로 보이며, 버튼 색도 전환 없이 바뀝니다.',
        kk = 'Лаунчер анимацияларын өшіреді: беттер, терезелер мен тізімдер жылжымай, біртіндеп пайда болмай бірден көрінеді, ал батырмалар түсін ауысусыз өзгертеді.',
    },
    -- FAF's own options whose help FAF's language files don't have yet (loc/<lang>/strings_db.lua; Traditional
    -- Chinese has them). The English is FAF's tooltip, shown from there; {i ...} names a key, filled in by LOC.
    commands_ignore_mode = {
        ru = 'Если включено, при удержании {i properkeyname_0123} принимаются только приказы движения. Так вы точно отдадите приказ двигаться, а не случайно начнёте сбор или атаку. Не действует при удержании {i properkeyname_0009}.',
        de = 'Wenn an, werden beim Halten von {i properkeyname_0123} nur Bewegungsbefehle angenommen. So gibst du sicher einen Bewegungsbefehl statt versehentlich Recycling oder Angriff. Gilt nicht beim Halten von {i properkeyname_0009}.',
        fr = "Si activé, maintenir {i properkeyname_0123} ne laisse passer que les ordres de déplacement. Cela garantit un ordre de déplacement plutôt qu'une récupération ou une attaque accidentelle. Sans effet en maintenant {i properkeyname_0009}.",
        pl = 'Gdy włączone, przy wciśniętym {i properkeyname_0123} przyjmowane są tylko rozkazy ruchu. Dzięki temu na pewno wydasz rozkaz ruchu, a nie przypadkiem odzysk lub atak. Nie działa przy wciśniętym {i properkeyname_0009}.',
        es = 'Si está activado, al mantener {i properkeyname_0123} solo se aceptan órdenes de movimiento. Así te aseguras de mover y no empezar por error un reciclaje o un ataque. No se aplica al mantener {i properkeyname_0009}.',
        it = "Se attivo, tenendo premuto {i properkeyname_0123} vengono accettati solo ordini di movimento. Così dai di sicuro un ordine di movimento invece di avviare per errore un recupero o un attacco. Non vale tenendo premuto {i properkeyname_0009}.",
        cz = 'Když je zapnuto, při držení {i properkeyname_0123} se přijímají jen rozkazy pohybu. Tak jistě dáte rozkaz k pohybu, ne omylem recyklaci nebo útok. Neplatí při držení {i properkeyname_0009}.',
        cn = '开启后，按住 {i properkeyname_0123} 时只接受移动命令，确保下达的是移动而不是误触回收或攻击。按住 {i properkeyname_0009} 时不生效。',
        ko = '켜면 {i properkeyname_0123}를 누르고 있는 동안 이동 명령만 받습니다. 실수로 회수나 공격을 시작하지 않고 확실히 이동하게 합니다. {i properkeyname_0009}를 누르고 있을 때는 적용되지 않습니다.',
        kk = 'Қосулы болса, {i properkeyname_0123} басулы тұрғанда тек жылжу бұйрықтары қабылданады. Сонда кездейсоқ жинау не шабуыл емес, нақты жылжу бұйрығы беріледі. {i properkeyname_0009} басулы болғанда әсер етпейді.',
    },
    selection_threshold_regular = {
        ru = 'Чем больше значение, тем легче выделять и выбирать целью юнитов и объекты. Значение — в пикселях экрана. Помогает выделять отдельных юнитов и объекты, особенно на мониторах с высоким разрешением. Юниты важнее объектов; если в радиусе несколько, выбирается ближайший к курсору.',
        de = 'Je höher der Wert, desto leichter lassen sich Einheiten und Objekte auswählen und anvisieren. Der Wert ist in Bildschirmpixeln. Hilft bei einzelnen Einheiten und Objekten, besonders auf hochauflösenden Bildschirmen. Einheiten gehen vor Objekten; sind mehrere in Reichweite, gilt die dem Mauszeiger nächste.',
        fr = "Plus la valeur est haute, plus il est facile de sélectionner et de cibler unités et objets. La valeur est en pixels d'écran. Aide à choisir une unité ou un objet précis, surtout sur les écrans à haute résolution. Les unités passent avant les objets ; parmi plusieurs à portée, la plus proche du curseur l'emporte.",
        pl = 'Im wyższa wartość, tym łatwiej zaznaczać i celować w jednostki i obiekty. Wartość w pikselach ekranu. Pomaga wybierać pojedyncze jednostki i obiekty, zwłaszcza na ekranach o wysokiej rozdzielczości. Jednostki mają pierwszeństwo przed obiektami; z kilku w zasięgu wygrywa najbliższy kursora.',
        es = 'Cuanto mayor el valor, más fácil seleccionar y apuntar a unidades u objetos. El valor está en píxeles de pantalla. Ayuda a elegir unidades u objetos sueltos, sobre todo en pantallas de alta resolución. Las unidades tienen prioridad sobre los objetos; si hay varios al alcance, gana el más cercano al cursor.',
        it = "Più alto è il valore, più è facile selezionare e mirare unità o oggetti. Il valore è in pixel dello schermo. Aiuta a scegliere singole unità o oggetti, specie su schermi ad alta risoluzione. Le unità hanno la precedenza sugli oggetti; se ce ne sono più a portata, vince il più vicino al cursore.",
        cz = 'Čím vyšší hodnota, tím snáz se vybírají a zaměřují jednotky a objekty. Hodnota je v pixelech obrazovky. Pomáhá vybrat jednotlivé jednotky a objekty, hlavně na obrazovkách s vysokým rozlišením. Jednotky mají přednost před objekty; z více v dosahu vyhrává nejbližší ke kurzoru.',
        cn = '数值越高，越容易选中和瞄准单位或物体。数值以屏幕像素计。有助于选中单个单位或物体，尤其在高分辨率显示器上。单位优先于物体；范围内有多个时，离光标最近的优先。',
        ko = '값이 클수록 유닛과 사물을 선택하고 겨냥하기 쉬워집니다. 값은 화면 픽셀 단위입니다. 특히 고해상도 화면에서 개별 유닛이나 사물을 고르는 데 도움이 됩니다. 유닛이 사물보다 우선이며, 범위 안에 여럿이면 커서에 가장 가까운 것이 우선입니다.',
        kk = 'Мән неғұрлым үлкен болса, бөлімшелер мен заттарды таңдау және нысанаға алу соғұрлым оңай. Мән экран пиксельдерімен. Әсіресе ажыратымдылығы жоғары экрандарда жеке бөлімшелер мен заттарды таңдауға көмектеседі. Бөлімшелер заттардан басым; аймақта бірнешеу болса, курсорға ең жақыны таңдалады.',
    },
    selection_threshold_reclaim = {
        ru = 'Чем больше значение, тем легче выделять и выбирать целью юнитов и объекты, в пикселях экрана. Этот порог действует в режиме сбора: так проще попадать каждым щелчком и меньше пустых приказов сбора. Юниты важнее объектов; из нескольких выбирается ближайший к курсору.',
        de = 'Je höher der Wert, desto leichter lassen sich Einheiten und Objekte auswählen und anvisieren, in Bildschirmpixeln. Diese Schwelle gilt im Recycling-Modus: Jeder Klick trifft leichter, und es gibt weniger leere Recycling-Befehle. Einheiten gehen vor Objekten; von mehreren gilt die dem Mauszeiger nächste.',
        fr = "Plus la valeur est haute, plus il est facile de sélectionner et de cibler unités et objets, en pixels d'écran. Ce seuil sert en mode récupération : chaque clic touche plus facilement et il y a moins d'ordres de récupération dans le vide. Les unités passent avant les objets ; parmi plusieurs, la plus proche du curseur l'emporte.",
        pl = 'Im wyższa wartość, tym łatwiej zaznaczać i celować w jednostki i obiekty, w pikselach ekranu. Ten próg działa w trybie odzysku: każde kliknięcie łatwiej trafia i jest mniej pustych rozkazów odzysku. Jednostki mają pierwszeństwo przed obiektami; z kilku wygrywa najbliższy kursora.',
        es = 'Cuanto mayor el valor, más fácil seleccionar y apuntar a unidades u objetos, en píxeles de pantalla. Este umbral se usa en modo reciclaje: cada clic acierta más y hay menos órdenes de reciclaje en vano. Las unidades tienen prioridad sobre los objetos; de varios, gana el más cercano al cursor.',
        it = "Più alto è il valore, più è facile selezionare e mirare unità o oggetti, in pixel dello schermo. Questa soglia vale in modalità recupero: ogni clic va a segno più facilmente e ci sono meno ordini di recupero a vuoto. Le unità hanno la precedenza sugli oggetti; tra più, vince il più vicino al cursore.",
        cz = 'Čím vyšší hodnota, tím snáz se vybírají a zaměřují jednotky a objekty, v pixelech obrazovky. Tento práh platí v režimu recyklace: každé kliknutí snáz trefí a je méně prázdných rozkazů k recyklaci. Jednotky mají přednost před objekty; z více vyhrává nejbližší ke kurzoru.',
        cn = '数值越高，越容易选中和瞄准单位或物体，以屏幕像素计。此阈值用于回收模式：每次点击更容易命中，减少落空的回收命令。单位优先于物体；有多个时，离光标最近的优先。',
        ko = '값이 클수록 유닛과 사물을 선택하고 겨냥하기 쉬워지며, 단위는 화면 픽셀입니다. 이 값은 회수 모드에서 쓰여, 클릭이 더 잘 맞고 헛된 회수 명령이 줄어듭니다. 유닛이 사물보다 우선이며, 여럿이면 커서에 가장 가까운 것이 우선입니다.',
        kk = 'Мән неғұрлым үлкен болса, бөлімшелер мен заттарды таңдау және нысанаға алу соғұрлым оңай, экран пиксельдерімен. Бұл шек жинау режимінде қолданылады: әр басу оңай тиеді, бос жинау бұйрықтары азаяды. Бөлімшелер заттардан басым; бірнешеуінен курсорға ең жақыны таңдалады.',
    },
    selection_threshold_replay = {
        ru = 'Чем больше значение, тем легче выделять и выбирать целью юнитов и объекты, в пикселях экрана. Этот порог действует при просмотре повтора: так проще наводить курсор на юнитов. Юниты важнее объектов; из нескольких выбирается ближайший к курсору.',
        de = 'Je höher der Wert, desto leichter lassen sich Einheiten und Objekte auswählen und anvisieren, in Bildschirmpixeln. Diese Schwelle gilt beim Ansehen eines Replays: Man trifft Einheiten mit dem Mauszeiger leichter. Einheiten gehen vor Objekten; von mehreren gilt die dem Mauszeiger nächste.',
        fr = "Plus la valeur est haute, plus il est facile de sélectionner et de cibler unités et objets, en pixels d'écran. Ce seuil sert en regardant un replay : survoler les unités est plus facile. Les unités passent avant les objets ; parmi plusieurs, la plus proche du curseur l'emporte.",
        pl = 'Im wyższa wartość, tym łatwiej zaznaczać i celować w jednostki i obiekty, w pikselach ekranu. Ten próg działa przy oglądaniu powtórki: łatwiej najechać kursorem na jednostki. Jednostki mają pierwszeństwo przed obiektami; z kilku wygrywa najbliższy kursora.',
        es = 'Cuanto mayor el valor, más fácil seleccionar y apuntar a unidades u objetos, en píxeles de pantalla. Este umbral se usa al ver una repetición: es más fácil pasar el cursor sobre las unidades. Las unidades tienen prioridad sobre los objetos; de varios, gana el más cercano al cursor.',
        it = "Più alto è il valore, più è facile selezionare e mirare unità o oggetti, in pixel dello schermo. Questa soglia vale guardando un replay: è più facile passare col cursore sulle unità. Le unità hanno la precedenza sugli oggetti; tra più, vince il più vicino al cursore.",
        cz = 'Čím vyšší hodnota, tím snáz se vybírají a zaměřují jednotky a objekty, v pixelech obrazovky. Tento práh platí při sledování záznamu: snáz najedete kurzorem na jednotky. Jednotky mají přednost před objekty; z více vyhrává nejbližší ke kurzoru.',
        cn = '数值越高，越容易选中和瞄准单位或物体，以屏幕像素计。此阈值用于观看录像：更容易把光标悬停在单位上。单位优先于物体；有多个时，离光标最近的优先。',
        ko = '값이 클수록 유닛과 사물을 선택하고 겨냥하기 쉬워지며, 단위는 화면 픽셀입니다. 이 값은 리플레이를 볼 때 쓰여, 유닛 위에 커서를 올리기 쉬워집니다. 유닛이 사물보다 우선이며, 여럿이면 커서에 가장 가까운 것이 우선입니다.',
        kk = 'Мән неғұрлым үлкен болса, бөлімшелер мен заттарды таңдау және нысанаға алу соғұрлым оңай, экран пиксельдерімен. Бұл шек қайталауды көргенде қолданылады: курсорды бөлімшелерге апару оңайырақ. Бөлімшелер заттардан басым; бірнешеуінен курсорға ең жақыны таңдалады.',
    },
    camera_shake_intensity = {
