        es = 'Resolución de las sombras (más baja = más rápido). Los valores altos necesitan más memoria de vídeo.',
        it = 'Risoluzione delle ombre (più bassa = più veloce). Valori alti richiedono più memoria video.',
        cz = 'Rozlišení stínů (nižší = rychlejší). Vysoké hodnoty potřebují víc grafické paměti.',
        cn = '阴影分辨率（越低越快）。数值高需要更多显存。',
