    shadow_render_distance = {
        ru = 'Дальность прорисовки теней (уровень детализации; ниже — быстрее). Высокие значения могут сильно снизить частоту кадров.',
        de = 'Sichtweite der Schatten (Detailstufe; niedriger = schneller). Hohe Werte können die Bildrate deutlich senken.',
        fr = "Distance d'affichage des ombres (niveau de détail ; plus bas = plus rapide). Les valeurs hautes peuvent nettement réduire les images par seconde.",
        pl = 'Odległość rysowania cieni (poziom szczegółów; niżej = szybciej). Wysokie wartości mogą mocno obniżyć liczbę klatek.',
        es = 'Distancia de dibujado de las sombras (nivel de detalle; más baja = más rápido). Los valores altos pueden bajar mucho los fotogramas por segundo.',
        it = 'Distanza di disegno delle ombre (livello di dettaglio; più bassa = più veloce). Valori alti possono ridurre molto i fotogrammi al secondo.',
