        cn = '阴影的绘制距离（细节等级，越低越快）。数值高会明显降低帧率。',
        tw = '陰影的繪製距離（細節等級，越低越快）。數值高會明顯降低幀率。',
        ko = '그림자를 그리는 거리(세부 수준)입니다(낮을수록 빠름). 높은 값은 프레임률을 크게 떨어뜨릴 수 있습니다.',
        kk = 'Көлеңкелерді салу қашықтығы (бөлшектену деңгейі; төменірек — жылдамырақ). Жоғары мәндер кадр жиілігін айтарлықтай төмендетуі мүмкін.',
    },
    frametime = {
        ru = 'Минимальное время кадра. Несовместимо с вертикальной синхронизацией: она выключается, когда вы двигаете ползунок и применяете настройки. Возможны разрывы изображения. Нужно, чтобы подогнать игру под частоту современных мониторов; учтите, что кадры часто упираются в процессор, а не в видеокарту, особенно в больших боях. Значения: 16 = 60 Гц, 10 = 100 Гц, 8 = 120 Гц, 7 = 144 Гц, 6 = 165 Гц.',
        de = 'Die kürzeste Bildzeit. Verträgt sich nicht mit vertikaler Synchronisation, die beim Verschieben und Übernehmen ausgeschaltet wird. Kann Bildrisse verursachen. Gedacht, um die Bildwiederholrate moderner Monitore zu treffen; die Bildrate hängt oft an der CPU statt der Grafikkarte, besonders in großen Gefechten. Werte: 16 = 60 Hz, 10 = 100 Hz, 8 = 120 Hz, 7 = 144 Hz, 6 = 165 Hz.',
        fr = "Le temps d'image minimal. Incompatible avec la synchronisation verticale, désactivée quand vous déplacez le curseur et appliquez. Peut causer des déchirures d'image. Sert à suivre la fréquence des écrans modernes ; les images par seconde sont souvent limitées par le processeur plutôt que la carte graphique, surtout dans les grands combats. Valeurs : 16 = 60 Hz, 10 = 100 Hz, 8 = 120 Hz, 7 = 144 Hz, 6 = 165 Hz.",
        pl = 'Najkrótszy czas klatki. Niezgodny z synchronizacją pionową, którą wyłącza przesunięcie suwaka i zastosowanie. Może powodować rozrywanie obrazu. Służy dopasowaniu do odświeżania nowoczesnych monitorów; liczbę klatek często ogranicza procesor, nie karta, zwłaszcza w dużych bitwach. Wartości: 16 = 60 Hz, 10 = 100 Hz, 8 = 120 Hz, 7 = 144 Hz, 6 = 165 Hz.',
        es = 'El tiempo mínimo de fotograma. Incompatible con la sincronización vertical, que se desactiva al mover el control y aplicar. Puede causar cortes de imagen. Sirve para ajustarse a la frecuencia de los monitores modernos; los fotogramas suelen depender de la CPU y no de la tarjeta gráfica, sobre todo en grandes batallas. Valores: 16 = 60 Hz, 10 = 100 Hz, 8 = 120 Hz, 7 = 144 Hz, 6 = 165 Hz.',
        it = "Il tempo minimo per fotogramma. Incompatibile con la sincronizzazione verticale, che si disattiva spostando il cursore e applicando. Può causare tearing. Serve ad adattarsi alla frequenza dei monitor moderni; i fotogrammi spesso dipendono dalla CPU e non dalla scheda video, specie nelle grandi battaglie. Valori: 16 = 60 Hz, 10 = 100 Hz, 8 = 120 Hz, 7 = 144 Hz, 6 = 165 Hz.",
        cz = 'Nejkratší doba snímku. Nesnese se s vertikální synchronizací, která se vypne posunutím jezdce a použitím. Může způsobit trhání obrazu. Slouží k přizpůsobení obnovovací frekvenci moderních monitorů; snímky často brzdí procesor, ne grafická karta, hlavně ve velkých bitvách. Hodnoty: 16 = 60 Hz, 10 = 100 Hz, 8 = 120 Hz, 7 = 144 Hz, 6 = 165 Hz.',
        cn = '最短帧时间。与垂直同步不兼容，移动滑块并应用后会自动关闭垂直同步。可能出现画面撕裂。用于贴合现代显示器的刷新率；帧率往往受限于 CPU 而非显卡，大规模战斗时尤其如此。常用值：16 = 60Hz，10 = 100Hz，8 = 120Hz，7 = 144Hz，6 = 165Hz。',
        ko = '최소 프레임 시간입니다. 수직 동기화와 함께 쓸 수 없으며, 슬라이더를 움직여 적용하면 수직 동기화가 꺼집니다. 화면 찢김이 생길 수 있습니다. 최신 모니터 주사율에 맞추기 위한 것이며, 특히 큰 전투에서는 그래픽 카드보다 CPU가 프레임률을 제한하는 경우가 많습니다. 값: 16 = 60Hz, 10 = 100Hz, 8 = 120Hz, 7 = 144Hz, 6 = 165Hz.',
        kk = 'Кадрдың ең қысқа уақыты. Тік синхрондаумен үйлеспейді: жүгірткіні жылжытып, қолданғанда ол өшеді. Кескін жыртылуы мүмкін. Заманауи мониторлардың жиілігіне сәйкестендіру үшін; кадр жиілігін көбіне бейнекарта емес, процессор шектейді, әсіресе үлкен шайқастарда. Мәндер: 16 = 60 Гц, 10 = 100 Гц, 8 = 120 Гц, 7 = 144 Гц, 6 = 165 Гц.',
    },
    launch_ignore_selection = {
        ru = 'Нацеливают ли пуски тактических ракет и ядерных ракет землю, не учитывая юнитов под курсором. Наведение прямо на юнита позволяет попадать по юнитам с хитбоксом над землёй (например, Megalith), делает точку удара постоянной и позволяет пускам в очереди следовать за движущейся целью между перезарядками.',
        de = 'Ob Starts taktischer Raketen und Atomraketen die Einheiten unter dem Mauszeiger übergehen und den Boden anvisieren. Direktes Zielen auf eine Einheit trifft Einheiten mit Trefferzone über dem Boden wie den Megalith, macht den Einschlagpunkt gleichbleibend und lässt eingereihte Starts dem Ziel zwischen den Nachladezeiten folgen.',
        fr = "Si les tirs de missiles tactiques et nucléaires ignorent les unités sous le curseur et visent le sol. Viser directement une unité permet de toucher celles dont la zone d'impact est au-dessus du sol, comme le Megalith, rend le point d'impact constant et laisse les tirs en file suivre la cible entre deux rechargements.",
        pl = 'Czy wystrzały pocisków taktycznych i atomowych pomijają jednostki pod kursorem i celują w ziemię. Celowanie bezpośrednio w jednostkę pozwala trafiać jednostki z hitboxem nad ziemią, jak Megalith, daje stały punkt trafienia i pozwala kolejnym wystrzałom w kolejce podążać za celem między przeładowaniami.',
        es = 'Si los lanzamientos de misiles tácticos y nucleares ignoran las unidades bajo el cursor y apuntan al suelo. Apuntar directamente a una unidad permite alcanzar unidades con su zona de impacto sobre el suelo, como el Megalith, hace constante el punto de impacto y deja que los lanzamientos en cola sigan al objetivo entre recargas.',
        it = "Se i lanci di missili tattici e nucleari ignorano le unità sotto il cursore e mirano al suolo. Mirare direttamente un'unità permette di colpire unità con hitbox sopra il suolo, come il Megalith, rende costante il punto d'impatto e fa seguire il bersaglio ai lanci in coda tra una ricarica e l'altra.",
        cz = 'Zda odpaly taktických a jaderných raket ignorují jednotky pod kurzorem a míří na zem. Míření přímo na jednotku zasáhne jednotky se zásahovou oblastí nad zemí, jako Megalith, drží místo dopadu stálé a dovolí raketám ve frontě sledovat cíl mezi nabíjením.',
        cn = '战术导弹和核弹的发射命令是否忽略光标下的单位而改为瞄准地面。直接瞄准单位可以命中判定框高于地面的单位（如 Megalith），让落点更稳定，并让排队的发射在装填间隙跟随移动的目标。',
        tw = '戰術飛彈和核彈的發射命令是否忽略游標下的單位而改為瞄準地面。直接瞄準單位可以命中判定框高於地面的單位（如 Megalith），讓落點更穩定，並讓排隊的發射在裝填間隙跟隨移動的目標。',
        ko = '전술 미사일과 핵미사일 발사 명령이 커서 아래 유닛을 무시하고 지면을 겨냥할지 정합니다. 유닛을 직접 겨냥하면 Megalith처럼 판정 범위가 지면 위에 있는 유닛도 맞히고, 착탄 지점이 일정해지며, 대기열의 발사가 재장전 사이에 움직이는 목표를 따라갑니다.',
        kk = 'Тактикалық және ядролық зымырандарды ұшыру бұйрықтары курсор астындағы бөлімшелерді елемей, жерді көздей ме, соны анықтайды. Бөлімшені тікелей көздеу хитбоксы жерден жоғары бөлімшелерге (мысалы, Megalith) тигізеді, соғу нүктесін тұрақты етеді және кезектегі ұшырулар қайта оқталу арасында жылжыған нысананы қуалайды.',
    },
    queue_reorder = {
