--- The game's language code, lower case ('us' when it has none).
function Language()
    return string.lower(tostring(rawget(_G, '__language') or 'us'))
end

--- The help of option `key` in the player's language, English when it has none in it, or '' for an option without.
function Help(key)
    local entry = texts[key]
    if not entry then
        return ''
    end
    return entry[Language()] or entry.us or ''
end

--- The help of option `key` in the player's language only: nil when it has none in that language (FAF's own text,
--- translated by the game, comes first then).
function Translated(key)
    local entry = texts[key]
    local language = Language()
    if not entry or language == 'us' then
        return nil
    end
    return entry[language]
end

--- Every key with help here (for the test walk).
function Keys()
    local keys = {}
    for key in texts do
        table.insert(keys, key)
    end
    table.sort(keys)
    return keys
end
